"""
Note that in the test file, all the functions are recommended not to return a complex object, and if there is a need to pass an object to the next
function call, put the object in the registry. The key of the object in the dictionary is the object name which is unique in current module.
This key-value caching method makes store and reuse of the intermediate object easier and yet will avoid the issue when the object is not serializable.

"""
#Ditionary to store intermediate objects which can be re-used later.
registry={"screen_recorder": None, "resume_workflow_retries": 1}

def start_recording(recording_output_dir=None):
    """
    Start recording for MIM. Will Create an instance of ScreenRecorder first if not exisitng and put the instance into registry.

    Args:
        recording_output_dir (str, optional): The directory where the recording output should be saved.
        If not provided, a default directory(cwd) will be used.

    Returns:
        None: This function initiates the recording process but does not return any value.

    """
    if registry["screen_recorder"] is None:
        registry["screen_recorder"] = ScreenRecorder(output_path=recording_output_dir)
    registry["screen_recorder"].start_recording()
    mLog(f"Started MIM recording...")

def stop_recording():
    """
    Stop recording of MIM.
    """
    if registry["screen_recorder"]:
        registry["screen_recorder"].stop_recording()
        mLog(f"Stopped MIM recording.")

def mim_start(app_file_path: str=r"C:\Program Files\MIM Software\MIM\bin\MIM_64.exe", bridge_dll_jre_bin_dir: str=r"C:\Program Files\MIM Software\MIM\bin"):
    """
    Start MIM, handle loading page, popups, notifications if any appears

    Args:
        app_file_path (str): The MIM app full path. Will use default one if not provided.
        bridge_dll_jre_bin_dir (str): The directory that contains the bridge dll's parent folder above 'JRE_(version)'.

    Returns:
        None

    """
    mLog("mim_start")
    is_64bit =  sys.maxsize > 2**32
    jre_version = "64" if is_64bit else "32"
    bridge_dll_file = fr"jre_{jre_version}\bin\windowsaccessbridge-{jre_version}.dll"
    bridge_dll_path = str(Path(bridge_dll_jre_bin_dir) / bridge_dll_file)

    for file_path in [app_file_path, bridge_dll_path]:
        if not Path(file_path).is_file():
            raise FileNotFoundError(f"File not found: {file_path}")

    title = "MIM 7*" # this parameter is optional
    jab = JABDriver(title=title, file_path=Path(app_file_path), bridge_dll=bridge_dll_path)
    registry["jab"] = jab
    mLog("AUT is starting...")
    if  not jab.initialized:
        jab.init_jab(jab.hwnd)

def await_mim(jab:JABDriver=None):
    """
    Await mim to fully starting.

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

    Returns:
        None

    """
    mLog("await_mim")
    jab = jab or registry.get("jab", None)
    if jab is None:
        raise ValueError("None object.")
    await_loading_page()
    handle_popups()
    #main page
    layered_pane = jab.wait_for_element(mim_objects.layered_pane_xpath, By.FULL_XPath)
    registry["layered_pane"] = layered_pane
    if not layered_pane:
        raise Exception("Runtime error")
    handle_notifictions()

def is_in_planning_workspace() -> bool:
    """
    Check if the current workspace is 'work_space_of_contours_and_dashboard_and_dose_and_4D'

    Returns:
        True: if the workspace is for contouring / planning activities,
        False: if the workspace is for patient selection and image set processing, or even not started.
    """
    jab = registry.get("jab", None)
    if jab:
        planning_workspace = jab.find_element_by_xpath(value = mim_objects.work_space_of_contours_and_databoard_and_dose_and_4D_xpath)
        if planning_workspace and planning_workspace.is_showing():
            print("In planning workspace")
            return True
    return False

def await_loading_page(jab:JABDriver=None):
    """
    Wait for loading page.

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

    Returns:
        None

    """
    mLog("await_loading_page")
    jab = jab or registry.get("jab", None)
    if jab is None:
        raise ValueError("None object.")

    patients_button = jab.find_element_by_xpath(mim_objects.patients_button_xpath)
    #loading page
    #loading_label = jab.wait_for_element(mim_objects.loading_label_xpath, By.FULL_XPath, timeout=5)
    loading_label = jab.root_element.wait_for_object({"uid":mim_objects.loading_label_uid}) if patients_button is None else None
    if loading_label:
        print("Loading MIM,please wait..", end = '.' )
        while loading_label:
            print(".", end = '.' )
            time.sleep(.08)
            frame = loading_label.nth_parent(4)
            if frame and not frame.is_showing():
                break
        print("done\n" )

def handle_popups(jab:JABDriver = None):
    """"
    Handle pop-up windows

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

    Returns:
        None

    """
    mLog("handle_popups")
    jab = jab or registry.get("jab", None)
    if jab is None:
        raise ValueError("None object.")
    #"Handle pop up windows if any
    ret = jab.handle_popup_window(mim_objects.title_button)
    if ret:
        mLog("Pop up windows handled")

def handle_notifictions(layered_pane:JABElement=None):
    """
    Handle notifications

    Args:
        layered_pane (JABElement, optional): The layered pane on which the notifications window resides.
        If None, layered_pane will point to the one in registry.

    Returns:
        None

    """
    mLog("handle_notifictions")
    layered_pane = layered_pane or registry.get("layered_pane", None)
    if layered_pane is None:
        raise ValueError("None object.")

    mLog("Check if Notifications window is here")
    notification_dialog = get_notifications_popup(layered_pane, 5)
    if notification_dialog:
        mLog("Handle the Notifications window")
        acknowledge_notification(notification_dialog, "No")
        acknowledge_notification(notification_dialog, "Dismiss")

def get_patient_name_id(pat_lastname:str=None, pat_firstname:str=None, pat_id:str=None) -> str:
    """
    Get patient name id string.

    Args:
        pat_lastname (str, optional): The last name of the patient. Defaults to None.
        pat_firstname (str, optional): The first name of the patient. Defaults to None.
        pat_id (str, optional): The unique identifier for the patient. Defaults to None.

    Returns:
        The patient name id string with the format defined in mim_test_data and filled
        with actual name(s)/id.

    Purpose:
        This function allows for flexible input of patient information. iF all are None's,
        The patient will be the one given in mim_test_data.
        If any of these parameters is not None, it will replace the corresponding one in mim_test_data.

    """
    if pat_lastname is not None:
        mim_test_data.patient_lastname = pat_lastname
    if pat_firstname is not None:
        mim_test_data.patient_firstname = pat_firstname
    if pat_id is not None:
        mim_test_data.patient_id = pat_id
    return mim_test_data.patient_name_id

def execute_launch_workflow(jab:JABDriver=None, workflow_name:str="", pat_lastname:str=None, pat_firstname:str=None, pat_id:str=None, session_date_time_id:str = ""):
    """
    Execute 'Launch Workflow'

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

        workflow_name (str, optional): The name of the workflow to be launched. If is empty, will use the one in mim_test_data if it is enabled.

        pat_lastname (str, optional): paitent last name. If not None, will use to replace the one in mim_test_data.

        pat_firstname (str, optional): paitent last name. If not None, will use to replace the one in mim_test_data.

        pat_id (str, optional): paitent id string. If not None, will use to replace the one in mim_test_data.

        session_date_time_id (str, optinal): session date time_

    Returns:
        None

    """
    #In the first(default initial) workspace
    mLog("execute_launch_workflow")
    jab = jab or registry.get("jab", None)
    if jab is None:
        raise ValueError("None object.")

    work_space_of_search_and_patient_data_and_actions = jab.wait_for_element(mim_objects.work_space_of_search_and_patient_data_and_actions_xpath)
    registry["work_space_of_search_and_patient_data_and_actions"] = work_space_of_search_and_patient_data_and_actions

    patient_name_id = get_patient_name_id(pat_lastname, pat_firstname, pat_id)
    select_patient(patient_name_id)
    #patient_data_page = registry.get("patient_data_page", None)
    choose_session(selected_session_date_time_id=session_date_time_id)
    if not workflow_name and mim_test_data.test_options["test_online_adaptive_workflow"]:
        workflow_name = 'Online Adaptive Dashboard'
    print(f"launch workflow:{workflow_name}")
    if workflow_name:
        select_and_launch_workflow(workflow_name=workflow_name)

def select_patient(patient_name_id:str=None, work_space_of_search_and_patient_data_and_actions:JABElement=None):
    """
    Select pateint from patient data page

    Args:
        patient_name_id (str, optional): The patient_name_id used to select patient.If None, patient_name_id will use the one in mim_test_data.

        work_space_of_search_and_patient_data_and_actions (JABElement, optional): the workspace element(containing 'search', 'patient data', 'actions' tabs). If None,
           it will point to the one in registry.

    Returns:
        True: if the specified patient selected.
        False: otherwise.

    """
    mLog("select_patient")

    work_space_of_search_and_patient_data_and_actions = work_space_of_search_and_patient_data_and_actions or registry.get("work_space_of_search_and_patient_data_and_actions", None)

    if work_space_of_search_and_patient_data_and_actions is None:
        raise ValueError("None object: work_space_of_search_and_patient_data_and_actions")

    #search_panel = work_space_of_search_and_patient_data_and_actions.find_element_by_xpath(mim_objects.search_panel_xpath)
    search_results_label = work_space_of_search_and_patient_data_and_actions.find_element_by_xpath(mim_objects.search_results_label_xpath)
    patient_list_panel = search_results_label.nth_parent(2) if search_results_label else None
    if not patient_list_panel:
        raise Exception("No patient loaded")

    patient_table = patient_list_panel.find_element_by_role("table")
    table = patient_table.table
    rows = table["row_count"]
    cols = table["column_count"]

    if patient_name_id is None:
        patient_name_id = get_patient_name_id()
    #Select the test patient from the patient list
    if patient_table:
        #note that for patient_name_id, the space in between is the non-breaking one (\xa0, instead of \x20)
        for i in range(rows):
            for j in range(cols):
                cell = patient_table.get_cell(i, j, True)
                time.sleep(1)
                if cell.role == "label" and cell.name == patient_name_id:
                    cell.click(True)
                    mLog("Select patient: " + patient_name_id.replace("\n","\t") ) #repr(mim_test_data.patient_name_id))
                    break

    #patient_data_label_xpath_with_notification =    "/root pane[@indexinparent=0]/layered pane[@indexinparent=1]/panel[@indexinparent=1]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=1]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=0]/label[@indexinparent=0 and @name='Patient Data"]"
    #patient_data_label_xpath_without_notification = "/root pane[@indexinparent=0]/layered pane[@indexinparent=1]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=1]/panel[@indexinparent=0]/panel[@indexinparent=0]/panel[@indexinparent=0]/label[@indexinparent=0 and @name='Patient Data"]"
    patient_data_label = work_space_of_search_and_patient_data_and_actions.wait_for_element(mim_objects.patient_data_label_xpath)
    if patient_data_label is None:
        raise Exception("Patient data label not found")

    patient_data_page = patient_data_label.nth_parent(2)
    registry["patient_data_page"] = patient_data_page
    sessions_tab = patient_data_page.find_element_by_xpath(mim_objects.sessions_tab_xpath)
    if not sessions_tab.is_selected():
        logger.error("Session not selected")
        return False
    return True

def choose_session(selected_session_date_time_id: str="", patient_data_page:JABElement=None) -> bool:
    """
    Choose session from session list.

    Args:
        selected_session_date_time_id (str, optional): the date time id of the session to be selected. If not provided, it will use the one
        in mim_test_data.
        patient_data_page (JABElement, optional): the patient data page element. If None, it will point to the one in registry.

    Returns:
        True: If the session is chosen.
        False: otherwise.

    """
    mLog("choose_session")
    #Choose a session from the Sessions dropdown
    patient_data_page = patient_data_page or registry.get("patient_data_page", None)
    if patient_data_page is None:
        raise ValueError("None object: patient_data_page")

    session_filter_button = patient_data_page.find_element_by_xpath(mim_objects.session_filter_button_xpath)
    sessions_panel = session_filter_button.nth_parent(2) if session_filter_button else None
    if sessions_panel:
        #sessions_combobox_role = "combo box"
        sessions_combobox = sessions_panel.find_element_by_role("combo box")
        if sessions_combobox:
            sessions_combobox.click(True)
    else:
        logger.error("Sessions not found. Please re-run.")
        return False

    if not selected_session_date_time_id:
        selected_session_date_time_id = mim_test_data.selected_session_date_id
    selected_session_date_time_label = sessions_panel.find_element_by_name(selected_session_date_time_id)
    selected_session = selected_session_date_time_label.nth_parent(2) if selected_session_date_time_label else None

    if selected_session:
        selected_session.click(True)
        mLog(f"Session of '{mim_test_data.selected_session_date_id}' is selected")
    else:
        logger.error("Session specified is not found. Please select the correct session")
        return False
    return True

def select_and_launch_workflow(workflow_name: str="", work_space_of_search_and_patient_data_and_actions: JABElement=None) -> bool:
    """
    Select and launch workflow

    Args:
        workflow_name (str, optinal): name of the workflow to be launched. If not provided, will use the one in mim_test_data.

        work_space_of_search_and_patient_data_and_actions (JABElement, optional): The workspace element(containing 'search', 'patient data', 'actions' tabs).
        If None, will point to the one in registry.

    Returns:
        True: if launched successfully.
        False: otherwise.

    """
    mLog("select_and_launch_workflow")
    if not workflow_name:
        mLog( "Workflow is not specified. Skipped.")
        return False

    #Select and launch workflow
    work_space_of_search_and_patient_data_and_actions = work_space_of_search_and_patient_data_and_actions or registry.get("work_space_of_search_and_patient_data_and_actions", None)
    if work_space_of_search_and_patient_data_and_actions is None:
        raise ValueError("None object.")

    actions_label = work_space_of_search_and_patient_data_and_actions.find_element_by_xpath(mim_objects.actions_label_xpath)

    actions_panel = actions_label.nth_parent(3) if actions_label else None  #actions_page = actions_panel.parent

    if actions_panel is None:
        logger.error("Actions Panel is not found. Please re-run.")
        return False

    #find online adaptive dashboard panel from the list and select it.
    workflow_list = actions_panel.find_element_by_xpath(mim_objects.workflow_list_xpath)

    #Locate online adaptive workflow from workflow list.
    if not workflow_list:
        logger.error("Workflow list is not found. Please re-run.")
        return False

    if workflow_name and not workflow_name.startswith('\n'):
        workflow_name = '\n' + workflow_name

    for wf in workflow_list.children:
        if wf.children_count > 0 and wf.children[0].children_count > 1 and wf.children[0].children[1].text == workflow_name:
            workflow_dashboard_panel = wf
            workflow_dashboard_panel.click(True) #.click()
            workflow_text = workflow_name.lstrip('\n')
            mLog(f"Selected '{workflow_text}' from the workflow list.")
            break
    # Launch online adaptive workflow
    launch_workflow_button = actions_panel.find_element_by_xpath(mim_objects.launch_workflow_button_xpath)
    if launch_workflow_button:
        launch_workflow_button.click(True)
        mLog(f"Clicked '{launch_workflow_button.name}' button")
        time.sleep(15)
    else:
        logger.error(f"Launch Workflow button: {mim_objects.launch_workflow_button_xpath} is not found. Please re-run.")
        return False
    return True

def execute_copy_contours(jab:JABDriver=None, layered_pane:JABElement=None, test_contour_expand_contract_rename: bool=None, test_copy_contour_from_reference_plan:bool=None, test_contour_qa:bool=None, test_save_and_export_to_monaco:bool=None):
    """
    Execute copy contours

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

        layered_pane (JABElement, optional): The layered pane on which the notifications window resides. If None, layered_pane will point to the one in registry.

        test_contour_expand_contract_rename (bool, optional): Flag to tell if to test contour expand/contract and rename. If None, will fall back on to the
           option in mim_test_data.

        test_copy_contour_from_reference_plan (bool, optional): Flag to tell if to test copy contour from reference plan. If None, will fall back on to the
           option in mim_test_data.

        test_contour_qa (bool, optional): Flag to tell if to test contour QA. If None, will fall back on to the
           option in mim_test_data.

        test_save_and_export_to_monaco (bool, optional): Flag to tell if to test save and export to Monaco. If None, will fall back on to the
           option in mim_test_data.

    Returns:
        None

    """
    #Now enter the second work space of Dashboard/Contours/Dose/4D...
    mLog("execute_copy_contours")
    jab = jab or registry.get("jab", None)
    layered_pane = layered_pane or registry.get("layered_pane",None)

    if jab is None or layered_pane is None:
        raise ValueError("None object.")

    locate_online_adaptive_dashboard()

    # contours_page = registry.get("contours_page", None)
    # online_adaptive_dashboard_panel = registry.get("online_adaptive_dashboard_panel", None)

    update_contour_display()

    if test_copy_contour_from_reference_plan is None:
        test_copy_contour_from_reference_plan = mim_test_data.test_options["test_copy_contour_from_reference_plan"]
    if test_copy_contour_from_reference_plan:
        copy_contours_from_reference_plan()

    if test_contour_expand_contract_rename is None:
        test_contour_expand_contract_rename = mim_test_data.test_options["test_contour_expand_contract_rename"]
    if test_contour_expand_contract_rename:
        contour_expand_contract_rename()

    work_space_of_contours_and_dashboard_and_dose_and_4D = registry.get("work_space_of_contours_and_dashboard_and_dose_and_4D", None)

    if work_space_of_contours_and_dashboard_and_dose_and_4D is None:
        raise ValueError("None object: work_space_of_contours_and_dashboard_and_dose_and_4D")

    if test_contour_qa is None:
        test_contour_qa = mim_test_data.test_options["test_contour_qa"]
    if test_contour_qa:
        contour_qa()

    if test_save_and_export_to_monaco is None:
        test_save_and_export_to_monaco = mim_test_data.test_options["test_save_and_export_to_monaco"]
    if test_save_and_export_to_monaco:
        save_and_export_to_monaco()

def locate_online_adaptive_dashboard(jab:JABDriver=None):
    """
    Locate 'Online Adaptive Dashboard'

    Args:
        jab (JABDriver, optional): The JAB driver instance. If None, jab will point to the one in registry.

    Returns:
        None

    """
    mLog("locate_online_adaptive_dashboard")

    jab = jab or registry.get("jab", None)
    if jab is None:
        raise ValueError("None object.")

    work_space_of_contours_and_dashboard_and_dose_and_4D = jab.wait_for_element(mim_objects.work_space_of_contours_and_databoard_and_dose_and_4D_xpath)

    registry["work_space_of_contours_and_dashboard_and_dose_and_4D"] = work_space_of_contours_and_dashboard_and_dose_and_4D

    if work_space_of_contours_and_dashboard_and_dose_and_4D:

        contours_label = work_space_of_contours_and_dashboard_and_dose_and_4D.wait_for_element(mim_objects.contours_label_xpath)

        contours_page = contours_label.nth_parent(3) if contours_label else None

        registry["contours_page"] = contours_page

        contours_and_dashboard_panel = contours_page.parent if contours_page else None

        dashboard_label = contours_and_dashboard_panel.find_element_by_xpath(mim_objects.dashboard_label_xpath) if contours_and_dashboard_panel else None

        if dashboard_label is None:
            logger.error("Dashboard is not found. Please re-run.")

        dashboard_page =  dashboard_label.nth_parent(3) if dashboard_label else None

        online_adaptive_dashboard_label = dashboard_page.find_element_by_xpath(mim_objects.online_adaptive_dashboard_label_xpath) if dashboard_page else None

        online_adaptive_dashboard_panel = online_adaptive_dashboard_label.nth_parent(2) if online_adaptive_dashboard_label else None

        registry["online_adaptive_dashboard_panel"] = online_adaptive_dashboard_panel

def update_contour_display(online_adaptive_dashboard_panel:JABElement=None):
    """
    'Update Contour Dispaly'

    Args:
        online_adaptive_dashboard_panel (JABElement, optional): online adaptive dashbord panel on which the contour controls resides. If None,
            will point to the one in registry.

    Returns:
        None

    """
    mLog("update_contour_display")
    online_adaptive_dashboard_panel = online_adaptive_dashboard_panel or registry.get("online_adaptive_dashboard_panel", None)
    if online_adaptive_dashboard_panel is None:
        raise ValueError("None object.")

    update_display_button = online_adaptive_dashboard_panel.wait_for_element(mim_objects.update_display_button_xpath,timeout=10) if online_adaptive_dashboard_panel else None
    if update_display_button:
        series_comboboxes = online_adaptive_dashboard_panel.find_elements_by_role("combo box")
        if series_comboboxes:
            for combobox in series_comboboxes:
                y_diff = update_display_button.bounds.get("y") - combobox.bounds.get("y") # type: ignore
                if y_diff == 32:
                    series_combobox = combobox
                    mLog("Found the series combo box")
                    break
            if series_combobox:
                series_combobox.click(True)
                reg_from_xvi = series_combobox.find_element_by_xpath(mim_objects.reg_from_xvi_xpath)
                if reg_from_xvi:
                    reg_from_xvi.click(True)
                    mLog(f"Series '{reg_from_xvi.name}' selected")
                time.sleep(1)
        mLog(f"Pressed '{update_display_button.name}' button")
        update_display_button.click(True) #.click()
        #Waiting for dislay update...
        time.sleep(10)

# Copy contours
def copy_contours_from_reference_plan(online_adaptive_dashboard_panel:JABElement=None, layered_pane:JABElement=None, jab:JABDriver=None):
    """
    'Copy Contours from Reference Plan'

    Args:
        online_adaptive_dashboard_panel (JABElement, optional): online adaptive dashbord panel on which the contour controls resides. If None,
            will point to the one in registry.

        layered_pane (JABElement, optional): The layered pane on which the notifications window resides. If None, it will point to the one in registry.

    Returns:
        None

    """
    mLog('test copy_contour_from_reference_plan')
    online_adaptive_dashboard_panel = online_adaptive_dashboard_panel or registry.get("online_adaptive_dashboard_panel", None)
    layered_pane = layered_pane or registry.get("layered_pane", None)
    jab = jab or registry.get("jab", None)

    if None in (jab, layered_pane, online_adaptive_dashboard_panel):
        raise ValueError("None object.")

    copy_contours_from_reference_plan_button = online_adaptive_dashboard_panel.wait_for_element(mim_objects.copy_contours_from_reference_plan_button_xpath)
    if copy_contours_from_reference_plan_button:
        mLog(f"Clicked '{copy_contours_from_reference_plan_button.name}' button")
        copy_contours_from_reference_plan_button.click() #.click(True)

        notification_dialog = get_notifications_popup(layered_pane, 20)
        while notification_dialog and notification_dialog.is_showing():
            notification_dialog = get_notifications_popup(layered_pane)

        #Return to Dashbord home
        return_to_dashboard_home_button = jab.wait_for_element(mim_objects.return_to_dashboard_home_button_xpath)
        if not return_to_dashboard_home_button:
            raise Exception(f"Button '{return_to_dashboard_home_button.name}' not found.")

        #registry["return_to_dashboard_home_button"] = return_to_dashboard_home_button

        #Select Copy Type and Name to copy
        copy_contours_panel = return_to_dashboard_home_button.nth_parent(2)
        combobox_label_dict = copy_contours_panel.find_elements_by_attributes({"role":["combo box", "label"]})

        labels = filter_by_attrs(combobox_label_dict["label"],
                                 [SearchAttribute(name="object_depth", value=22, strict=True),
                                  SearchAttribute(name="name", value=2, comparator = lambda val, min_len: len(str(val)) > min_len)]
                                 )
        comboboxes = combobox_label_dict["combo box"]
        label_combobox_map = same_line_control_matching(labels, comboboxes)

        _, structures_without_contours = divide_structures_list(jab)

        #for contour_name, copy_method in mim_test_data.structure_generation_method_map_in_imrt_constraints.items():
        copy_method = "Rigid"
        for structure_name in structures_without_contours:
            combobox = label_combobox_map[structure_name] if structure_name in label_combobox_map else None
            if not combobox:
                continue
            combobox.click(True)
            copy_method_list = combobox.find_element_by_role("list")
            for item in copy_method_list.children:
                if item.name == copy_method:
                    #item.click()
                    item.click(True)
                    mLog(f"{structure_name}: {copy_method}")
                    break

        scroll_pane_of_dashboard = return_to_dashboard_home_button.nth_parent(8) if return_to_dashboard_home_button else None
        scroll_bar_of_online_adaptive_dashboard = scroll_pane_of_dashboard.find_element_by_uid(mim_objects.scroll_bar_of_online_adaptive_dashboard_uid) if scroll_pane_of_dashboard else None
        if scroll_bar_of_online_adaptive_dashboard and scroll_bar_of_online_adaptive_dashboard.scroll():
            mLog("Scroll the bar")

        copy_selected_contours_to_xvi_image_button = copy_contours_panel.find_element_by_xpath(mim_objects.copy_selected_contours_to_xvi_image_button_xpath) # type: ignore
        if copy_selected_contours_to_xvi_image_button:
            mLog(f"Clicked '{copy_selected_contours_to_xvi_image_button.name}' button")
            copy_selected_contours_to_xvi_image_button.click(True)
            time.sleep(3)
            notification_dialog = get_notifications_popup(layered_pane, 20)
            acknowledge_notification(notification_dialog, "OK")
            while notification_dialog and notification_dialog.is_showing():
                notification_dialog = get_notifications_popup(layered_pane)

        if return_to_dashboard_home_button:
            if scroll_bar_of_online_adaptive_dashboard and scroll_bar_of_online_adaptive_dashboard.scroll(False):
                mLog("Scroll the bar back")
            mLog(f"Clicked '{return_to_dashboard_home_button.name}' button")
            return_to_dashboard_home_button.click(True) #.click()

def contour_expand_contract_rename(contours_page:JABElement = None, layered_pane: JABElement=None):
    """
    Contour expand/Contract and Rename

    Args:
        contours_page (JABElement, optional): contours page element. If None, it Will point to the one in registry.

        layered_pane (JABElement, optional): The layered pane on which the notifications window resides. If None, it will point to the one in registry.

    Returns:
        None
    """
    mLog("contour_expand_contract_rename")
    contours_page = contours_page or registry.get("contours_page", None)
    layered_pane = layered_pane or registry.get("layered_pane", None)

    if layered_pane is None or contours_page is None:
        raise ValueError("None object.")

    if contours_page:
        selected_contour_xpath = mim_objects.contour_xpath_template.format(mim_test_data.selected_contour_name_to_edit)
        selected_contour = contours_page.wait_for_element(selected_contour_xpath)
        if selected_contour:
            mLog(f"Selected '{mim_test_data.selected_contour_name_to_edit}' from the Contours tab")
            selected_contour.click(True)

        expand_contract_button = contours_page.wait_for_element(mim_objects.expand_contract_button_xpath)
        if expand_contract_button:
            mLog(f"Selected '{expand_contract_button.description}' icon")
            expand_contract_button.click(True) #.click()

        notification_dialog = get_notifications_popup(layered_pane, 120)
        contour_name_text = notification_dialog.wait_for_element(mim_objects.contour_name_text_xpath) if notification_dialog else None
        if contour_name_text:
            contour_name_text.click(True)
            mLog(f"In destination field on notifications dialog, change 'ROI-*' to {mim_test_data.new_contour_name} and select 'OK' ")
            contour_name_text.send_text(mim_test_data.new_contour_name)
            time.sleep(1)
    notification_dialog = get_notifications_popup(layered_pane, 20)
    acknowledge_notification(notification_dialog, "OK")

