def save_and_export_to_monaco(online_adaptive_dashboard_panel: JABElement=None, layered_pane:JABElement=None):
    """
    Save and Export to Monaco

    Args:
        online_adaptive_dashboard_panel (JABElment, optional): online adaptive dashboard element where the 'save and export to monaco' button resides.

        layered_pane (JABElement, optional): The layered pane on which the notifications window resides. If None, it will point to the one in registry.

    Returns:
        None

    """
    online_adaptive_dashboard_panel = online_adaptive_dashboard_panel or registry.get("online_adaptive_dashboard_panel", None)
    layered_pane = layered_pane or registry.get("layered_pane", None)

    if layered_pane is None or online_adaptive_dashboard_panel is None:
        raise ValueError("None object.")

    save_and_export_to_monaco_button = online_adaptive_dashboard_panel.wait_for_element(mim_objects.save_and_export_to_monaco_button_xpath)
    if save_and_export_to_monaco_button:
        save_and_export_to_monaco_button.click()
        mLog(f"Clicked '{save_and_export_to_monaco_button.name}' button")
        time.sleep(3)
        notification_dialog = get_notifications_popup(layered_pane, 120)
        resume_workflow_attempts = 0
        while notification_dialog and notification_dialog.is_showing() and resume_workflow_attempts < registry["resume_workflow_retries"]:
            mLog("Selecting Resume Workflow...")
            notification_dialog = get_notifications_popup(layered_pane)
            acknowledge_notification(notification_dialog, "Resume Workflow")
            resume_workflow_attempts += 1
            time.sleep(2)
            acknowledge_notification(notification_dialog, "Close")

def set_resume_workflow_retries(times:int):
    """
    Set 'Resume Workflow' click retries. Use registry['resume_workflow_retries'] later as the times of clicks on the 'Resume Workflow' button.

    Args:
        times (int):  The number to be set as click counts on the 'Resume Workflow' button. The default value is 1.

    Returns:
        None
    """
    registry["resume_workflow_retries"] = times


