def mim_workflow():
    """
    MIM workflow functions combined for the workflow
    """
    mim_start()
    await_mim()
    workflow_name = ""
    if mim_test_data.test_options["test_online_adaptive_workflow"]:
        workflow_name = 'Online Adaptive Dashboard'
    execute_launch_workflow(workflow_name=workflow_name)
    execute_copy_contours()

def run_automation_test():
    """
    A sample test with recording.
    """
    try:
        if mim_test_data.test_options["enable_recording"]:
            start_recording()
        mLog("Test begins"+">"*90)
        mim_workflow()
        mLog("Test ends"+ "|"*90)
        time.sleep(1)
    finally:
        if mim_test_data.test_options["enable_recording"]:
            stop_recording()